export const TILE_SIZE = 256;
export const MIN_LEVEL = -40;
export const MAX_LEVEL = 40;
export const LIVE_TILE_MIN_PX = 64;
export const SUB_PIXEL_PX = 1;
import { MAX_LEVEL, MIN_LEVEL, TILE_SIZE } from "./constants";

export type Point = { x: number; y: number };

export type BBox = { minX: number; minY: number; maxX: number; maxY: number };

export type Tile = { level: number; tx: number; ty: number };

export function clampLevel(level: number): number {
  return Math.min(MAX_LEVEL, Math.max(MIN_LEVEL, level)) + 0;
}

export function tileWorldSize(level: number): number {
  return TILE_SIZE * 2 ** level;
}

export function gridOrigin(level: number): number {
  return level === MAX_LEVEL ? -tileWorldSize(MAX_LEVEL) / 2 : 0;
}

export function tileScreenSize(level: number, zoom: number): number {
  return tileWorldSize(level) * zoom;
}

export function nativeLevel(zoom: number): number {
  if (!(zoom > 0) || !Number.isFinite(zoom)) {
    throw new RangeError(`zoom must be a positive finite number, got ${zoom}`);
  }
  return clampLevel(Math.ceil(-Math.log2(zoom)));
}

export function tileIndex(level: number, coordinate: number): number {
  return Math.floor((coordinate - gridOrigin(level)) / tileWorldSize(level)) + 0;
}

export function tileAt(level: number, point: Point): Tile {
  return { level, tx: tileIndex(level, point.x), ty: tileIndex(level, point.y) };
}

function tileMin(level: number, index: number): number {
  return gridOrigin(level) + index * tileWorldSize(level);
}

export function tileBounds(tile: Tile): BBox {
  return {
    minX: tileMin(tile.level, tile.tx),
    minY: tileMin(tile.level, tile.ty),
    maxX: tileMin(tile.level, tile.tx + 1),
    maxY: tileMin(tile.level, tile.ty + 1),
  };
}

export function tileKey(tile: Tile): string {
  return `${tile.level}:${tile.tx}:${tile.ty}`;
}

export function coarser(tile: Tile): Tile {
  const bounds = tileBounds(tile);
  return tileAt(tile.level + 1, { x: bounds.minX, y: bounds.minY });
}

export function toTileLocal(tile: Tile, point: Point): Point {
  const size = tileWorldSize(tile.level);
  return {
    x: ((point.x - tileMin(tile.level, tile.tx)) / size) * TILE_SIZE,
    y: ((point.y - tileMin(tile.level, tile.ty)) / size) * TILE_SIZE,
  };
}

export function fromTileLocal(tile: Tile, local: Point): Point {
  const size = tileWorldSize(tile.level);
  return {
    x: tileMin(tile.level, tile.tx) + (local.x / TILE_SIZE) * size,
    y: tileMin(tile.level, tile.ty) + (local.y / TILE_SIZE) * size,
  };
}

export function contains(outer: BBox, inner: BBox): boolean {
  return (
    outer.minX <= inner.minX &&
    outer.minY <= inner.minY &&
    inner.maxX <= outer.maxX &&
    inner.maxY <= outer.maxY
  );
}
import { LIVE_TILE_MIN_PX, MAX_LEVEL, MIN_LEVEL, SUB_PIXEL_PX, TILE_SIZE } from "./constants";
import { type BBox, clampLevel, nativeLevel, tileIndex } from "./tile";

export type LevelRange = {
  level: number;
  minTx: number;
  minTy: number;
  maxTx: number;
  maxTy: number;
};

export type ViewTiles = { native: number; live: LevelRange[]; snapshot: LevelRange[] };

export function levelRange(level: number, bounds: BBox): LevelRange {
  return {
    level,
    minTx: tileIndex(level, bounds.minX),
    minTy: tileIndex(level, bounds.minY),
    maxTx: tileIndex(level, bounds.maxX),
    maxTy: tileIndex(level, bounds.maxY),
  };
}

function levelForScreenSize(px: number, zoom: number): number {
  return clampLevel(Math.ceil(Math.log2(px / (TILE_SIZE * zoom))));
}

export function finestLevel(zoom: number): number {
  return levelForScreenSize(SUB_PIXEL_PX, zoom);
}

export function finestLiveLevel(zoom: number): number {
  return levelForScreenSize(LIVE_TILE_MIN_PX, zoom);
}

export function viewTiles(bounds: BBox, zoom: number): ViewTiles {
  const native = nativeLevel(zoom);
  const liveFrom = finestLiveLevel(zoom);
  const live: LevelRange[] = [];
  const snapshot: LevelRange[] = [];
  for (let level = MAX_LEVEL; level >= Math.max(MIN_LEVEL, finestLevel(zoom)); level--) {
    (level >= liveFrom ? live : snapshot).push(levelRange(level, bounds));
  }
  return { native, live, snapshot };
}

export function isSubPixel(bbox: BBox, zoom: number): boolean {
  return Math.max(bbox.maxX - bbox.minX, bbox.maxY - bbox.minY) * zoom < SUB_PIXEL_PX;
}
import type { BBox, Point } from "./tile";
import { isSubPixel } from "./view";

export const MARKER_PX = 2;
export const MARKER_ALPHA = 0.7;

export type Cull = "Draw" | "Marker" | "Skip";

export type Marker = { x: number; y: number; style: string };

const intersects = (a: BBox, b: BBox): boolean =>
  a.minX <= b.maxX && b.minX <= a.maxX && a.minY <= b.maxY && b.minY <= a.maxY;

export function cull(bbox: BBox, view: BBox, zoom: number): Cull {
  if (!intersects(bbox, view)) return "Skip";
  return isSubPixel(bbox, zoom) ? "Marker" : "Draw";
}

export const bboxCentre = (bbox: BBox): Point => ({
  x: (bbox.minX + bbox.maxX) / 2,
  y: (bbox.minY + bbox.maxY) / 2,
});

export function dedupeMarkers(markers: Iterable<Marker>): Marker[] {
  const cells = new Map<string, Marker>();
  for (const { x, y, style } of markers) {
    const cx = Math.floor(x / MARKER_PX);
    const cy = Math.floor(y / MARKER_PX);
    cells.set(`${cx}:${cy}`, { x: cx * MARKER_PX, y: cy * MARKER_PX, style });
  }
  return [...cells.values()];
}
import type { Point } from "./tile";

export function segmentDistance(p: Point, a: Point, b: Point): number {
  const dx = b.x - a.x;
  const dy = b.y - a.y;
  const lengthSquared = dx * dx + dy * dy;
  const t =
    lengthSquared === 0
      ? 0
      : Math.max(0, Math.min(1, ((p.x - a.x) * dx + (p.y - a.y) * dy) / lengthSquared));
  return Math.hypot(p.x - (a.x + t * dx), p.y - (a.y + t * dy));
}

const ELLIPSE_ITERATIONS = 4;

// Distance to the outline, by the trig-free iteration on the ellipse's evolute.
export function ellipseDistance(p: Point, centre: Point, rx: number, ry: number): number {
  const px = Math.abs(p.x - centre.x);
  const py = Math.abs(p.y - centre.y);
  const a = Math.abs(rx);
  const b = Math.abs(ry);
  if (a === 0 || b === 0) {
    return segmentDistance({ x: px, y: py }, { x: 0, y: 0 }, { x: a, y: b });
  }
  let tx = Math.SQRT1_2;
  let ty = Math.SQRT1_2;
  for (let i = 0; i < ELLIPSE_ITERATIONS; i++) {
    const x = a * tx;
    const y = b * ty;
    const ex = ((a * a - b * b) * tx ** 3) / a;
    const ey = ((b * b - a * a) * ty ** 3) / b;
    const r = Math.hypot(x - ex, y - ey);
    const q = Math.hypot(px - ex, py - ey);
    if (q === 0) break;
    tx = Math.min(1, Math.max(0, ((px - ex) * (r / q) + ex) / a));
    ty = Math.min(1, Math.max(0, ((py - ey) * (r / q) + ey) / b));
    const t = Math.hypot(tx, ty);
    tx /= t;
    ty /= t;
  }
  return Math.hypot(px - a * tx, py - b * ty);
}

export function insideEllipse(p: Point, centre: Point, rx: number, ry: number): boolean {
  if (rx === 0 || ry === 0) return false;
  return ((p.x - centre.x) / rx) ** 2 + ((p.y - centre.y) / ry) ** 2 <= 1;
}
import type { BBox, Point } from "@stallion/geometry";
import { MAX_LEVEL, MIN_LEVEL } from "@stallion/geometry";

export type Camera = { x: number; y: number; zoom: number };

export const MIN_ZOOM = 2 ** -MAX_LEVEL;
export const MAX_ZOOM = 2 ** -MIN_LEVEL;

export const clampZoom = (zoom: number): number => Math.min(MAX_ZOOM, Math.max(MIN_ZOOM, zoom));

export const screenToWorld = (camera: Camera, screen: Point): Point => ({
  x: camera.x + screen.x / camera.zoom,
  y: camera.y + screen.y / camera.zoom,
});

export const worldToScreen = (camera: Camera, world: Point): Point => ({
  x: (world.x - camera.x) * camera.zoom,
  y: (world.y - camera.y) * camera.zoom,
});

export const viewBounds = (camera: Camera, width: number, height: number): BBox => ({
  minX: camera.x,
  minY: camera.y,
  maxX: camera.x + width / camera.zoom,
  maxY: camera.y + height / camera.zoom,
});

export const pan = (camera: Camera, dx: number, dy: number): Camera => ({
  x: camera.x - dx / camera.zoom,
  y: camera.y - dy / camera.zoom,
  zoom: camera.zoom,
});

export const zoomTo = (camera: Camera, screen: Point, target: number): Camera => {
  const anchor = screenToWorld(camera, screen);
  const zoom = clampZoom(target);
  return { x: anchor.x - screen.x / zoom, y: anchor.y - screen.y / zoom, zoom };
};

export const zoomAt = (camera: Camera, screen: Point, factor: number): Camera =>
  zoomTo(camera, screen, camera.zoom * factor);

export type PinchStep = { anchor: Point; factor: number; dx: number; dy: number };

export const pinch = (camera: Camera, step: PinchStep): Camera =>
  pan(zoomAt(camera, step.anchor, step.factor), step.dx, step.dy);

export const wheelFactor = (deltaY: number, deltaMode: number): number => {
  const pixels = deltaMode === 1 ? deltaY * 16 : deltaMode === 2 ? deltaY * 800 : deltaY;
  return 2 ** (-pixels / 300);
};
import { MAX_LEVEL, MIN_LEVEL, nativeLevel } from "@stallion/geometry";

export type LevelOption = { level: number; current: boolean; hasContent: boolean };

export const LEVEL_ANIMATION_MS = 250;

export const levelOf = (zoom: number): number => nativeLevel(zoom);

export const zoomForLevel = (level: number): number => 2 ** -level;

export function levelOptions(current: number, contentLevels: Iterable<number>): LevelOption[] {
  const content = new Set(contentLevels);
  const levels = [current, ...content];
  const deepest = Math.max(MIN_LEVEL, Math.min(...levels) - 1);
  const shallowest = Math.min(MAX_LEVEL, Math.max(...levels) + 1);
  return Array.from({ length: shallowest - deepest + 1 }, (_, index) => {
    const level = deepest + index;
    return { level, current: level === current, hasContent: content.has(level) };
  });
}

export const easeOut = (t: number): number => 1 - (1 - t) ** 3;
import type { StoredObject } from "@stallion/client-store";
import {
  type BBox,
  fromTileLocal,
  nativeLevel,
  type Point,
  place,
  TILE_SIZE,
  type Tile,
  toTileLocal,
} from "@stallion/geometry";
import {
  MAX_WIDTH,
  MIN_WIDTH,
  nearestColour,
  nearestSize,
  PALETTE_RGB,
  type PencilSize,
  rgbHex,
  type Stroke,
  type Point as StrokePoint,
  type StrokeStyle,
  styleOf,
  widthOf,
} from "@stallion/schema";
import getStroke, { type StrokeOptions } from "perfect-freehand";

export const PALETTE: readonly string[] = PALETTE_RGB.map(rgbHex);

export const PENCIL_SIZES: readonly PencilSize[] = ["Small", "Medium", "Large"];

export const WIDTH_PRESETS: readonly number[] = [0.5, 1, 2, 40, 60, 96];

export const WIDTH_SLIDER_STEPS = 100;

const WIDTH_SPAN = Math.log(MAX_WIDTH / MIN_WIDTH);

const roundWidth = (width: number): number =>
  width < 4 ? Math.round(width * 2) / 2 : Math.round(width);

export const clampWidth = (width: number): number =>
  Math.min(MAX_WIDTH, Math.max(MIN_WIDTH, roundWidth(width)));

export const sliderToWidth = (step: number): number =>
  clampWidth(MIN_WIDTH * Math.exp((step / WIDTH_SLIDER_STEPS) * WIDTH_SPAN));

export const widthToSlider = (width: number): number =>
  Math.round((Math.log(clampWidth(width) / MIN_WIDTH) / WIDTH_SPAN) * WIDTH_SLIDER_STEPS);

export const MAX_POINTS = 4096;

export const strokeWorldWidth = (width: number, nativeZoom: number): number =>
  width * 2 ** (nativeZoom - 0.5);

const strokeOptions = (size: number, last: boolean): StrokeOptions => ({
  size,
  thinning: 0.5,
  smoothing: 0.5,
  streamline: 0.4,
  simulatePressure: false,
  last,
});

export const HIGHLIGHTER_ALPHA = 0.4;

export const UNIFORM_PRESSURE = 0.5;

export const outlinePath = (
  points: readonly StrokePoint[],
  size: number,
  last: boolean,
): Path2D => {
  const outline = getStroke([...points], strokeOptions(size, last));
  const path = new Path2D();
  const [first, ...rest] = outline;
  if (!first) return path;
  path.moveTo(first[0], first[1]);
  for (const [x, y] of rest) path.lineTo(x, y);
  path.closePath();
  return path;
};

const centrelinePath = (points: readonly StrokePoint[]): Path2D => {
  const path = new Path2D();
  const [first, ...rest] = points;
  if (!first) return path;
  path.moveTo(first[0], first[1]);
  if (rest.length === 0) path.lineTo(first[0], first[1]);
  for (const [x, y] of rest) path.lineTo(x, y);
  return path;
};

export type StrokeInk = { style: StrokeStyle; path: Path2D; lineWidth: number };

export const strokeInk = (
  style: StrokeStyle,
  points: readonly StrokePoint[],
  size: number,
  last: boolean,
): StrokeInk => {
  if (style === "Dashed") return { style, path: centrelinePath(points), lineWidth: size };
  const pressed =
    style === "Uniform" ? points.map(([x, y]): StrokePoint => [x, y, UNIFORM_PRESSURE]) : points;
  return { style, path: outlinePath(pressed, size, last), lineWidth: size };
};

export const dashPattern = (lineWidth: number): number[] => [lineWidth, lineWidth * 2.5];

export const paintInk = (
  ctx: CanvasRenderingContext2D,
  ink: StrokeInk,
  colour: string,
  alpha = 1,
): void => {
  const highlighter = ink.style === "Highlighter";
  ctx.globalAlpha = highlighter ? alpha * HIGHLIGHTER_ALPHA : alpha;
  if (highlighter) ctx.globalCompositeOperation = "multiply";
  if (ink.style === "Dashed") {
    ctx.strokeStyle = colour;
    ctx.lineWidth = ink.lineWidth;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";
    ctx.setLineDash(dashPattern(ink.lineWidth));
    ctx.stroke(ink.path);
    ctx.setLineDash([]);
  } else {
    ctx.fillStyle = colour;
    ctx.fill(ink.path);
  }
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = "source-over";
};

const randomHex = (bytes: number): string =>
  Array.from(crypto.getRandomValues(new Uint8Array(bytes)), (byte) =>
    byte.toString(16).padStart(2, "0"),
  ).join("");

export const newObjectId = (): string =>
  `${Date.now().toString(36).padStart(9, "0")}${randomHex(6)}`;

export type Draft = {
  objectId: string;
  rgb: number;
  width: number;
  style: StrokeStyle;
  nativeZoom: number;
  points: StrokePoint[];
};

export const startDraft = (
  rgb: number,
  width: number,
  style: StrokeStyle,
  zoom: number,
): Draft => ({
  objectId: newObjectId(),
  rgb,
  width,
  style,
  nativeZoom: nativeLevel(zoom),
  points: [],
});

export const continueDraft = (draft: Draft): Draft => {
  const last = draft.points.at(-1);
  return { ...draft, objectId: newObjectId(), points: last ? [last] : [] };
};

const pointsBounds = (points: readonly StrokePoint[], margin: number): BBox => {
  const xs = points.map((p) => p[0]);
  const ys = points.map((p) => p[1]);
  return {
    minX: Math.min(...xs) - margin,
    minY: Math.min(...ys) - margin,
    maxX: Math.max(...xs) + margin,
    maxY: Math.max(...ys) + margin,
  };
};

export const finishDraft = (draft: Draft): StoredObject | undefined => {
  if (draft.points.length === 0) return undefined;
  const bbox = pointsBounds(draft.points, strokeWorldWidth(draft.width, draft.nativeZoom));
  const placed = place(bbox);
  if (!placed.ok) return undefined;
  const { tile } = placed;
  const stroke: Stroke = {
    type: "Stroke",
    objectId: draft.objectId,
    nativeZoom: draft.nativeZoom,
    bbox,
    colour: nearestColour(draft.rgb),
    rgb: draft.rgb,
    size: nearestSize(draft.width),
    width: draft.width,
    style: draft.style,
    points: draft.points.map(([x, y, pressure]) => {
      const local = toTileLocal(tile, { x, y });
      return [local.x, local.y, pressure];
    }),
  };
  return { tile, object: stroke };
};

export type StrokeFrame = { origin: Point; scale: number; points: StrokePoint[] };

// Path2D keeps float32, so points live relative to the stroke bbox, never the tile.
export const strokeFrame = (tile: Tile, stroke: Stroke): StrokeFrame => {
  const { bbox } = stroke;
  const origin = { x: bbox.minX, y: bbox.minY };
  const extent = Math.max(
    bbox.maxX - bbox.minX,
    bbox.maxY - bbox.minY,
    strokeWorldWidth(widthOf(stroke), stroke.nativeZoom),
  );
  const scale = extent / TILE_SIZE;
  const points = stroke.points.map(([x, y, pressure]): StrokePoint => {
    const world = fromTileLocal(tile, { x, y });
    return [(world.x - origin.x) / scale, (world.y - origin.y) / scale, pressure];
  });
  return { origin, scale, points };
};

export const strokeFrameInk = (stroke: Stroke, frame: StrokeFrame): StrokeInk =>
  strokeInk(
    styleOf(stroke),
    frame.points,
    strokeWorldWidth(widthOf(stroke), stroke.nativeZoom) / frame.scale,
    true,
  );

export const draftScreenInk = (
  draft: Pick<Draft, "width" | "style" | "nativeZoom" | "points">,
  toScreen: (world: Point) => Point,
  zoom: number,
): StrokeInk =>
  strokeInk(
    draft.style,
    draft.points.map(([x, y, pressure]) => {
      const screen = toScreen({ x, y });
      return [screen.x, screen.y, pressure];
    }),
    strokeWorldWidth(draft.width, draft.nativeZoom) * zoom,
    false,
  );

export const translateStroke = (
  tile: Tile,
  stroke: Stroke,
  dx: number,
  dy: number,
): StoredObject | undefined => {
  const bbox = {
    minX: stroke.bbox.minX + dx,
    minY: stroke.bbox.minY + dy,
    maxX: stroke.bbox.maxX + dx,
    maxY: stroke.bbox.maxY + dy,
  };
  const placed = place(bbox);
  if (!placed.ok) return undefined;
  const points = stroke.points.map(([x, y, pressure]): StrokePoint => {
    const world = fromTileLocal(tile, { x, y });
    const local = toTileLocal(placed.tile, { x: world.x + dx, y: world.y + dy });
    return [local.x, local.y, pressure];
  });
  return { tile: placed.tile, object: { ...stroke, bbox, points } };
};

export type Scale = { anchor: Point; sx: number; sy: number };

export const scaleAbout = ({ anchor, sx, sy }: Scale, point: Point): Point => ({
  x: anchor.x + (point.x - anchor.x) * sx,
  y: anchor.y + (point.y - anchor.y) * sy,
});

const worldPoints = (tile: Tile, stroke: Stroke): StrokePoint[] =>
  stroke.points.map(([x, y, pressure]): StrokePoint => {
    const world = fromTileLocal(tile, { x, y });
    return [world.x, world.y, pressure];
  });

export const strokeExtent = (tile: Tile, stroke: Stroke): BBox =>
  pointsBounds(worldPoints(tile, stroke), 0);

export const scaleStroke = (tile: Tile, stroke: Stroke, scale: Scale): StoredObject | undefined => {
  const scaled = worldPoints(tile, stroke).map(([x, y, pressure]): StrokePoint => {
    const world = scaleAbout(scale, { x, y });
    return [world.x, world.y, pressure];
  });
  const bbox = pointsBounds(scaled, strokeWorldWidth(widthOf(stroke), stroke.nativeZoom));
  const placed = place(bbox);
  if (!placed.ok) return undefined;
  const points = scaled.map(([x, y, pressure]): StrokePoint => {
    const local = toTileLocal(placed.tile, { x, y });
    return [local.x, local.y, pressure];
  });
  return { tile: placed.tile, object: { ...stroke, bbox, points } };
};

