    if (f.kind === "Unsubscribe") ws.subscribed.delete(f.tileKey);
  } catch {}
});

await page.goto(`${ORIGIN}/b/${boardId}`, { waitUntil: "load" });
await page.locator("canvas.surface").waitFor({ state: "visible", timeout: 20000 });
await page.waitForTimeout(2500);
const W = 1440, H = 900, cx = W / 2, cy = H / 2;
if (scenario === "drawn") {
  for (let s = 0; s < 6; s++) {
    const y0 = 250 + s * 70;
    await page.mouse.move(350, y0);
    await page.mouse.down();
    for (let i = 1; i <= 40; i++) await page.mouse.move(350 + i * 18, y0 + Math.sin(i / 4) * 40, { steps: 1 });
    await page.mouse.up();
  }
  for (const kind of ["Ellipse", "Rectangle"]) {
    const btn = page.getByRole("button", { name: kind, exact: true });
    if (await btn.count()) { await btn.first().click(); }
    else { errors.push(`no ${kind} button`); continue; }
    await page.mouse.move(cx - 300, cy - 200);
    await page.mouse.down();
    await page.mouse.move(cx + 300, cy + 200, { steps: 10 });
    await page.mouse.up();
  }
  await page.waitForTimeout(1500);
}
const level = async () => Number(await page.locator(".level-chip").innerText());
await page.screenshot({ path: join(OUT, `level-0.png`) });
const rows = [];
const snap = async (lvl) => {
  await page.evaluate(() => { const s = window.__stats; for (const k of Object.keys(s)) s[k] = Array.isArray(s[k]) ? [] : 0; });
  const recv0 = ws.recv, bytes0 = ws.recvBytes, t0 = Date.now();
  for (let i = 0; i < 30; i++) { await page.mouse.wheel(0, i % 2 ? 0.5 : -0.5); await page.waitForTimeout(33); }
  const secs = (Date.now() - t0) / 1000;
  const st = await page.evaluate(() => window.__stats);
  const m = Object.fromEntries((await cdp.send("Performance.getMetrics")).metrics.map((x) => [x.name, x.value]));
  const frames = st.frames || 1;
  const sorted = [...st.rafMs].sort((a, b) => a - b);
  const v = ws.lastView;
  const row = {
    level: lvl,
    heapMB: +(m.JSHeapUsedSize / 1048576).toFixed(1),
    rssMB: pid ? rssTree(pid) : null,
    frames,
    rafAvgMs: +(st.rafMs.reduce((a, b) => a + b, 0) / frames).toFixed(2),
    rafP95Ms: +(sorted[Math.floor(sorted.length * 0.95)] ?? 0).toFixed(2),
    rafMaxMs: +(sorted.at(-1) ?? 0).toFixed(2),
    callsPerFrame: +((st.fill + st.stroke + st.fillRect + st.strokeRect) / frames).toFixed(1),
    lineToPerFrame: Math.round(st.lineTo / frames),
    wsRecvPerS: +((ws.recv - recv0) / secs).toFixed(1),
    wsKBPerS: +((ws.recvBytes - bytes0) / 1024 / secs).toFixed(1),
    subscribed: ws.subscribed.size,
    snapshotTiles: ws.snapshots.size,
    viewW: v ? +(v.maxX - v.minX).toPrecision(4) : null,
    viewH: v ? +(v.maxY - v.minY).toPrecision(4) : null,
    zoom: v?.zoom,
  };
  rows.push(row);
  console.log(JSON.stringify(row));
  await page.screenshot({ path: join(OUT, `level${lvl}.png`) });
};
await snap(await level());
let profiling = false;
for (let target = -1; target >= -9; target--) {
  if (target === -7 && !profiling) { await cdp.send("Profiler.enable"); await cdp.send("Profiler.start"); profiling = true; }
  if (mode === "chip") {
    await page.locator(".level-chip").click();
    await page.getByRole("option", { name: new RegExp(`^Level ${target}(,|$)`) }).click();
    await page.waitForTimeout(600);
  } else {
    let guard = 0;
    while ((await level()) > target && guard++ < 200) {
      for (let k = 0; k < 10; k++) await page.mouse.wheel(0, -10);
      await page.waitForTimeout(16);
    }
  }
  await page.waitForTimeout(800);
  await snap(await level());
}
if (profiling) {
  const { profile } = await cdp.send("Profiler.stop");
  writeFileSync(join(OUT, "zoom-7-to-9.cpuprofile"), JSON.stringify(profile));
  const self = new Map();
  const byId = new Map(profile.nodes.map((n) => [n.id, n]));
  const dt = profile.timeDeltas; const counts = new Map();
  profile.samples.forEach((id, i) => counts.set(id, (counts.get(id) ?? 0) + (dt[i] ?? 0)));
  for (const [id, us] of counts) { const n = byId.get(id); const key = `${n.callFrame.functionName || "(anon)"} ${n.callFrame.url.split("/").pop()}:${n.callFrame.lineNumber}`; self.set(key, (self.get(key) ?? 0) + us); }
  const top = [...self].sort((a, b) => b[1] - a[1]).slice(0, 12).map(([k, us]) => `${(us / 1000).toFixed(0)}ms ${k}`);
  console.log("PROFILE top self:\n" + top.join("\n"));
}
writeFileSync(join(OUT, "rows.json"), JSON.stringify({ boardId, scenario, mode, rows, errors, sentKinds: ws.sent, recvKinds: ws.recvKinds }, null, 1));
console.log("board", boardId, "errors", errors.length, errors.slice(0, 5), "sent", ws.sent, "recv", ws.recvKinds);
await browser.close();
EOF
