    const ell = (dash) => () => { ctx.fillStyle = "#fff"; ctx.fillRect(0,0,2880,1800); ctx.beginPath(); ctx.ellipse(1440 + 300*z, 900, 300*z, 200*z, 0, 0, Math.PI*2); ctx.lineWidth = 2*z; ctx.setLineDash(dash ? [2*z, 5*z] : []); ctx.stroke(); ctx.setLineDash([]); };
    const rect = () => { ctx.beginPath(); ctx.rect(1440 - 0, 900 - 200*z, 500*z, 400*z); ctx.lineWidth = 2*z; ctx.stroke(); };
    const p = new Path2D(); for (let i = 0; i <= 200; i++) { const a = i/200*Math.PI*2; p.lineTo(128+120*Math.cos(a), 128+120*Math.sin(a)); } p.closePath();
    const path = () => { ctx.setTransform(z*2,0,0,z*2,1440-128*z*2+120*z*2,900-128*z*2); ctx.fill(p); ctx.setTransform(1,0,0,1,0,0); };
    res[lvl] = { ellipse: time(ell(false)), dashedEllipse: time(ell(true)), rect: time(rect), path: time(path) };
  }
  return res;
});
console.table(out);
await browser.close();
EOF
